//  WHAT: Small, exact pieces of Swift source: a string literal from any text, a type name from a command or field
//        name, a doc comment from a sentence. What every generator writes with, so the same plan always writes the
//        same bytes.

import Foundation

enum SwiftText {
    /// The header every generated file opens with.
    static let generatedHeader = """
        //  GENERATED by Crafted from the port's plan (commands.json and the unit contracts). Do not edit: a new plan
        //  writes it again.
        """

    /// The first line of a body that stands in for a port, so nothing that holds it ships.
    static let stubMarker = "// crafted:stub"

    /// `text` as a Swift string literal on one line.
    static func literal(_ text: String) -> String {
        var out = "\""
        for scalar in text.unicodeScalars {
            switch scalar {
            case "\\": out += "\\\\"
            case "\"": out += "\\\""
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            default:
                if scalar.value < 0x20 || scalar.value == 0x7F {
                    out += "\\u{" + String(scalar.value, radix: 16) + "}"
                } else {
                    out.unicodeScalars.append(scalar)
                }
            }
        }
        return out + "\""
    }

    /// `tip` → `Tip`, `convertLength` → `ConvertLength`, `rate_table` → `RateTable`.
    static func pascal(_ name: String) -> String {
        name.split(whereSeparator: { $0 == "_" || $0 == "-" || $0 == " " }).map { part in
            part.prefix(1).uppercased() + part.dropFirst()
        }.joined()
    }

    /// A doc comment, `indent` deep, wrapped at 116 columns.
    static func doc(_ text: String, indent: String = "") -> String {
        let words = text.replacingOccurrences(of: "\n", with: " ").split(separator: " ")
        guard !words.isEmpty else { return "" }
        var lines: [String] = []
        var line = indent + "///"
        for word in words {
            if line.count + 1 + word.count > 116, line != indent + "///" {
                lines.append(line)
                line = indent + "///"
            }
            line += " " + word
        }
        lines.append(line)
        return lines.joined(separator: "\n") + "\n"
    }

    /// Whether `value` can be an enum case as it is.
    static func isPlainCase(_ value: String) -> Bool { SwiftTypeName.isIdentifier(value) && !keywords.contains(value) }

    /// A case name for a value that is not one: `°C` → `c`, `2x` → `v2x`, `in` → `in_`.
    static func caseName(_ value: String) -> String {
        var name = String(value.unicodeScalars.filter { $0.isASCII && (CharacterSet.alphanumerics.contains($0) || $0 == "_") }.map(Character.init))
        if name.isEmpty { name = "value" }
        if let first = name.first, first.isNumber { name = "v" + name }
        if keywords.contains(name) { name += "_" }
        return name
    }

    /// Swift's reserved words, which no generated name may be.
    static let keywords: Swift.Set<String> = [
        "associatedtype", "class", "deinit", "enum", "extension", "fileprivate", "func", "import", "init", "inout", "internal",
        "let", "open", "operator", "private", "protocol", "public", "rethrows", "static", "struct", "subscript", "typealias",
        "var", "break", "case", "continue", "default", "defer", "do", "else", "fallthrough", "for", "guard", "if", "in",
        "repeat", "return", "switch", "where", "while", "as", "Any", "catch", "false", "is", "nil", "super", "self", "Self",
        "throw", "throws", "true", "try", "await", "async", "some", "any", "Type", "Protocol",
    ]
}
